{"l":9586,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","q":"Hvad betyder 'to bury the hatchet'?","o":["at skjule noget","at begrave stridsøksen","at holde begravelse","at hugge brænde"],"a":"at begrave stridsøksen","r":"Udtrykket betyder at slutte fred."},
