{"l":9610,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","q":"Hvad betyder 'to leave no stone unturned'?","o":["at lade alt ligge","at kaste med sten","at bygge en mur","at vende hver en sten"],"a":"at vende hver en sten","r":"Udtrykket betyder at gøre alt for at finde noget."},
